#define UNITS_2   1
#define UNITS_SI  2
#define EX_USAGE  64

#define FTS_PHYSICAL  0x01
#define FTS_LOGICAL   0x02
#define FTS_COMFOLLOW 0x04
#define FTS_XDEV      0x08

#define howmany(x, y) (((x) + ((y) - 1)) / (y))

